    model.get_layer("layer2_1_pw_bn").set_weights([params["backbone.layer2.0.pw_bn.weight"].numpy(),
                                                   params["backbone.layer2.0.pw_bn.bias"].numpy(),
                                                   params["backbone.layer2.0.pw_bn.running_mean"].numpy(),
                                                   params["backbone.layer2.0.pw_bn.running_var"].numpy()])
